+  <a class="skip-link" href="#main-content">Skip to main content</a>
+  <div id="app"></div>
+
+  <script>
+    const fields = {
+      fullName: {
+        label: "Full name",
+        required: true,
+        autocomplete: "name",
+        inputMode: "text"
+      },
+      email: {
+        label: "Email address",
+        required: true,
+        autocomplete: "email",
+        inputMode: "email"
+      },
+      phone: {
+        label: "Phone number",
+        required: false,
+        autocomplete: "tel",
+        inputMode: "tel",
+        helpText: "Optional. Use digits, spaces, parentheses, or hyphens, for example +1 555 123 4567."
+      }
+    };
+
+    function FieldLabel(fieldId, config) {
+      return `
+        <label for="${fieldId}">
+          ${config.label}
+          ${config.required ? '<span class="required-indicator" aria-hidden="true"> *</span>' : ' <span class="field-optional">(optional)</span>'}
