+      `;
+    }
+
+    function FormField(fieldId, config) {
+      const inputType = fieldId === "email" ? "email" : fieldId === "phone" ? "tel" : "text";
+      const describedBy = [config.helpText ? `${fieldId}-help` : null].filter(Boolean).join(" ");
+
+      return `
+        <div class="form-field">
+          ${FieldLabel(fieldId, config)}
+          <input
+            id="${fieldId}"
+            name="${fieldId}"
+            type="${inputType}"
+            autocomplete="${config.autocomplete}"
+            inputmode="${config.inputMode}"
+            ${config.required ? "required" : ""}
+            aria-describedby="${describedBy}"
