+            </div>
+          </div>
+        </main>
+      `;
+    }
+
+    function renderApp() {
+      document.getElementById("app").innerHTML = App();
+    }
+
+    function validateField(fieldId, value) {
+      const trimmedValue = value.trim();
+
+      if (fieldId === "fullName") {
+        if (!trimmedValue) {
+          return "Error: Enter your full name.";
+        }
+        return "";
+      }
+
+      if (fieldId === "email") {
+        if (!trimmedValue) {
+          return "Error: Enter your email address.";
+        }
+        const emailPattern = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
+        if (!emailPattern.test(trimmedValue)) {
+          return "Error: Enter a valid email address like name@example.com.";
+        }
+        return "";
+      }
+
+      if (fieldId === "phone") {
+        if (!trimmedValue) {
+          return "";
+        }
+        const phonePattern = /^\+?[0-9()\-\s]{7,20}$/;
+        if (!phonePattern.test(trimmedValue)) {
+          return "Error: Enter a phone number in the format +1 555 123 4567.";
+        }
+      }
+
+      return "";
+    }
+
+    function updateFieldState(input, message) {
+      const errorElement = document.getElementById(`${input.id}-error`);
+      const helpId = document.getElementById(`${input.id}-help`) ? `${input.id}-help` : "";
+      const describedByIds = [helpId, message ? `${input.id}-error` : ""].filter(Boolean).join(" ");
+
+      input.setAttribute("aria-describedby", describedByIds);
+      input.setAttribute("aria-invalid", message ? "true" : "false");
+      errorElement.textContent = message;
+      errorElement.hidden = !message;
+    }
+
+    function attachFormBehavior() {
+      const form = document.getElementById("support-form");
+      const status = document.getElementById("form-status");
+      const orderedFields = ["fullName", "email", "phone"];
+
+      orderedFields.forEach((fieldId) => {
+        const input = document.getElementById(fieldId);
+        input.addEventListener("blur", () => {
+          updateFieldState(input, validateField(fieldId, input.value));
+        });
+
+        input.addEventListener("input", () => {
+          const nextMessage = validateField(fieldId, input.value);
+          if (input.getAttribute("aria-invalid") === "true" || !nextMessage) {
+            updateFieldState(input, nextMessage);
+          }
+          status.textContent = "";
+        });
+      });
+
+      form.addEventListener("submit", (event) => {
+        event.preventDefault();
+        status.textContent = "";
+
+        const invalidInputs = orderedFields
+          .map((fieldId) => {
+            const input = document.getElementById(fieldId);
+            const message = validateField(fieldId, input.value);
+            updateFieldState(input, message);
+            return message ? input : null;
+          })
+          .filter(Boolean);
+
+        if (invalidInputs.length > 0) {
+          invalidInputs[0].focus();
+          return;
+        }
+
+        status.textContent = "Your support request is ready to send. A specialist will follow up soon.";
+        form.reset();
+
+        orderedFields.forEach((fieldId) => {
+          const input = document.getElementById(fieldId);
+          updateFieldState(input, "");
+        });
+      });
+    }
+
+    renderApp();
+    attachFormBehavior();
+  </script>
+</body>
+</html>
+

