    wcag: wcag.map((v) => ({ id: v.id, impact: v.impact, targets: v.nodes.map((n) => n.target) })),
    bp: bp.map((v) => ({ id: v.id, impact: v.impact, targets: v.nodes.map((n) => n.target) }))
  }, null, 2));
  process.exit(wcag.length ? 1 : 0);
})().catch(async (error) => {
  console.error(error && error.message ? error.message : String(error));
  process.exit(2);
});
