             ${describedByAttribute}
             aria-errormessage="${fieldId}-error"
           >
           ${config.helpText ? `<p class="field-help" id="${fieldId}-help">${config.helpText}</p>` : ""}
           <p class="field-error" id="${fieldId}-error" hidden aria-live="polite"></p>
         </div>
       `;
     }

     function InfoPanel() {
       return `
         <aside class="info-panel" aria-labelledby="support-highlights-title">
           <h2 id="support-highlights-title">Why teams reach out here</h2>
           <p>Use this form for account help, billing questions, and product troubleshooting. A support specialist will reply using the email address you provide.</p>
           <ul class="feature-list">
             <li>
               <strong>Fast triage</strong>
               Your message is routed to the right support queue as soon as it is submitted.
             </li>
             <li>
               <strong>Clear follow-up</strong>
               We use your contact details only to respond to this request.
             </li>
             <li>
               <strong>Built for mobile</strong>
               The form stays readable and easy to complete on smaller screens.
             </li>
           </ul>
         </aside>
       `;
     }

     function ContactForm() {
       return `
         <section class="form-panel" aria-labelledby="contact-form-title">
           <h2 id="contact-form-title">Tell us how we can help</h2>
           <p class="form-intro">Share your contact details and we will follow up with the next steps.</p>
           <p class="required-note"><span class="required-indicator" aria-hidden="true">*</span> Required fields</p>
           <form id="support-form" novalidate>
             ${FormField("fullName", fields.fullName)}
             ${FormField("email", fields.email)}
             ${FormField("phone", fields.phone)}
             <div class="button-row">
               <button class="submit-button" type="submit">Send request</button>
               <p class="status-message" id="form-status" role="status" aria-live="polite"></p>
             </div>
           </form>
         </section>
       `;
     }

     function App() {
       return `
         <main id="main-content" tabindex="-1">
           <div class="page-shell">
             <section class="hero" aria-labelledby="page-title">
               <div class="hero-badge">Support</div>
               <h1 id="page-title">Contact our support team</h1>
               <p>Get help with your workspace, account, or active product issues using the support form below.</p>
             </section>
             <div class="content-grid">
               ${InfoPanel()}
               ${ContactForm()}
             </div>
           </div>
         </main>
       `;
     }

     function renderApp() {
       document.getElementById("app").innerHTML = App();
     }

     function validateField(fieldId, value) {
       const trimmedValue = value.trim();

       if (fieldId === "fullName") {
         if (!trimmedValue) {
           return "Error: Enter your full name.";
         }
         return "";
       }

       if (fieldId === "email") {
         if (!trimmedValue) {
           return "Error: Enter your email address.";
         }
         const emailPattern = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
         if (!emailPattern.test(trimmedValue)) {
           return "Error: Enter a valid email address like name@example.com.";
         }
         return "";
       }

       if (fieldId === "phone") {
         if (!trimmedValue) {
           return "";
         }
         const phonePattern = /^\+?[0-9()\-\s]{7,20}$/;
         if (!phonePattern.test(trimmedValue)) {
           return "Error: Enter a phone number in the format +1 555 123 4567.";
         }
       }

       return "";
     }

     function updateFieldState(input, message) {
       const errorElement = document.getElementById(`${input.id}-error`);
       const helpId = document.getElementById(`${input.id}-help`) ? `${input.id}-help` : "";
       const describedByIds = [helpId, message ? `${input.id}-error` : ""].filter(Boolean).join(" ");

       if (describedByIds) {
         input.setAttribute("aria-describedby", describedByIds);
       } else {
         input.removeAttribute("aria-describedby");
       }
       input.setAttribute("aria-invalid", message ? "true" : "false");
       errorElement.textContent = message;
       errorElement.hidden = !message;
     }

     function attachFormBehavior() {
       const form = document.getElementById("support-form");
       const status = document.getElementById("form-status");
       const orderedFields = ["fullName", "email", "phone"];

       orderedFields.forEach((fieldId) => {
         const input = document.getElementById(fieldId);
         input.addEventListener("blur", () => {
           updateFieldState(input, validateField(fieldId, input.value));
         });

         input.addEventListener("input", () => {
           const nextMessage = validateField(fieldId, input.value);
           if (input.getAttribute("aria-invalid") === "true" || !nextMessage) {
             updateFieldState(input, nextMessage);
           }
           status.textContent = "";
         });
       });

       form.addEventListener("submit", (event) => {
         event.preventDefault();
         status.textContent = "";

         const invalidInputs = orderedFields
           .map((fieldId) => {
             const input = document.getElementById(fieldId);
             const message = validateField(fieldId, input.value);
             updateFieldState(input, message);
             return message ? input : null;
           })
           .filter(Boolean);

         if (invalidInputs.length > 0) {
           invalidInputs[0].focus();
           return;
         }

         status.textContent = "Thanks. Your support request has been submitted.";
         form.reset();

         orderedFields.forEach((fieldId) => {
           const input = document.getElementById(fieldId);
           updateFieldState(input, "");
         });
       });
     }

     renderApp();
     attachFormBehavior();
   </script>
 </body>
 </html>

